j:jelly.script:
     function ${jvar_name}_showPreview() {
       var rel = gel('preview_${jvar_name}');
       var row = rel.value;     
       ${jvar_name}_showRecordPreview('${jvar_table}', '${jvar_fields}', '${jvar_name}', row);
     }

     addLoadEvent(${jvar_name}_showPreview); 

     function ${jvar_name}_previewForward(el) {
       var row = (el.value * 1) + 1;
       el.value = row;

       ${jvar_name}_showPreview();
     }

     function ${jvar_name}_previewBackward(el) {
       var row = (el.value * 1) - 1;
       if (row &lt; 1)
         row = 1;

       el.value = row;

       ${jvar_name}_showPreview();
     }

     function ${jvar_name}_singleRecordResponse(request, args) {
       var divname = args[0];
       var preview = document.getElementById(divname);
       clearNodes(preview);
       if (request.responseXML.documentElement) {
	  var items = request.responseXML.getElementsByTagName("item");
          for(var iCnt = 0; iCnt &lt; items.length; iCnt++) {
		var item = items[iCnt];
		var name = item.getAttribute("label");
		var tr = document.createElement('tr');
		var tdLabel = document.createElement('td');

		tdLabel.setAttribute('noWrap', 'true');
		var label = document.createElement('label');
                label.setAttribute('for', name);
		label.appendChild(document.createTextNode("\u00a0" + name));
		tdLabel.appendChild(label);
		tr.appendChild(tdLabel);
		var tdValue = document.createElement('td');
		tr.appendChild(tdValue);
		label = document.createElement('label');
                label.setAttribute('title', name);

		var evalue = item.getAttribute("value");
		label.appendChild(document.createTextNode(evalue));
		tdValue.appendChild(label);
  		preview.appendChild(tr);
         }
       }
     }

     function ${jvar_name}_showRecordPreview(table, field_list, divname, row) {
        if (!field_list)
          field_list = ${jvar_name}_fields;

    	var ajax = new GlideAjax("SingleRecord");
    	ajax.addParam("sysparm_name", table);
    	ajax.addParam("sysparm_field_list", field_list);
    	ajax.addParam("sysparm_row", row);
    	ajax.addParam("sysparm_type", "SingleRecord");

        ajax.getXML(${jvar_name}_singleRecordResponse, null, new Array(divname));
     }
